// live/text_talk_ru.js: what the townsfolk say; generated by tools/talk_build.py from docs/talk/*.json, edit those.
(function (root) {
  (root.TEXT || (root.TEXT = {})).talk = {"smith":{"lines":[["Горн сегодня горит ровно, и мне большего не надо.","Поесть ещё надо, это правда."],["Дай мне свою вещь, и я перекую её заново.","Свойства лягут иначе, а лучше или хуже, решает железо."],["{@child} опять пытался поднять мой молот.","Молот он не поднял, поэтому я сделал ему молоточек."],["{@sweeper} ругается, что от меня летит сажа.","Я стал бить потише, но сажи меньше не стало."],["Торговец опять полез вниз за стариной.","Я врезал ему в дверь крепкий замок, а он ушёл в окно."],["Гвоздь я держу двумя пальцами, и он меня боится.","Я с ним ласково говорю. Ты только никому не рассказывай."],["{@enchanter} говорит, что моя работа слишком громкая.","Я молчу, хотя её колбы тоже иногда бахают."],["Вмятины на твоих вещах я считаю каждый раз.","Вещи мне жалко. Тебя тоже, но это между нами."],["Ты заходи ко мне, когда будешь наверху.","Железо хорошее, только разговаривает мало."],["Слышишь, как поёт железо? Сегодня оно в духе.","Вчера оно молчало, и я весь день переживал."],["Искры кусаются, я проверял.","Поэтому у меня на руках нет ни одного волоска."],["{@elder} просит меня выковать ему кочергу.","Он просит её каждую неделю и держит при этом в руке."],["Если перековка не понравится, приходи снова.","Я не обижусь, а молот у меня незлобивый."],["Не стой у наковальни, дорогой человек.","Наковальня тебя простит, а я себя нет."],["Торговец должен мне за сорок подков.","Лошади у него нет. Что он с ними делает, я не спрашиваю."],["Мне дают подержать младенца, потому что руки большие.","Я стою и не дышу. Малышу нравится, а мне страшно."],["Я иногда хожу постоять рядом с нашим стражем.","Мы стоим и молчим. Очень хорошо поговорили."],["Внизу железо только ржавеет, и мне его жалко.","Когда приносишь домой старую вещь, я радуюсь ей, как родне."],["Мне тут сказали, что у меня доброе лицо.","Это сажа. Под сажей там всё строже."],["Я сегодня смотрел, как ты уходишь вниз.","Сказать мне нечего, но смотрел я долго."],["Подмастерье мне не нужен, я справляюсь один.","{@child} этого не знает и приходит каждое утро."],["Огонь для горна я беру от костра на площади.","Ему столько лет, что я всегда здороваюсь."],["{@merchant} пробовал со мной торговаться.","Я всё время молчал, и он сам поднял цену вдвое."],["Мне сказали, что я пою за работой.","Я думал, что это пел горн. Теперь мне неловко."],["У хорошего клинка я сразу спрашиваю, кто его ковал.","Он обычно не отвечает, но я всё равно спрашиваю."],["Застёгивай куртку, когда пойдёшь вниз.","Так просила передать {@sweeper}, а я только передаю."],["Молот у меня один, и второго мне не надо.","Второму пришлось бы объяснять всё с начала."],["В шести городах до нас тоже были кузнецы.","Мне приятно думать, что и они ругались на мехи."],["Если тебя там внизу обидят, ты мне скажи.","Вниз я не пойду, зато очень расстроюсь."],["{@porter} носит мне уголь и всё время улыбается.","Я дал ему мешок потяжелее, а он улыбается дальше."]],"asks":{"kill":["Внизу расплодились твари, и возню слышно даже у меня в кузнице. Сходишь к ним вместо меня? Мне не вырваться, у меня работа.","Там внизу развелось слишком много зубастых. Мне за тебя страшно, но за остальных ещё страшнее. Убавишь их немного?","Стук снизу мешает мне ковать. Сходи, пожалуйста, и разгони тех, кто там стучит. Можно насовсем."],"clear":["Внизу есть старые залы, и они забиты тварями. Людям там ходить страшно. Очистишь несколько, ладно?","Там когда-то были чьи-то мастерские, а теперь в них сидят твари. Мне за мастерские обидно. Выгони их оттуда, пожалуйста.","Я прошу редко. Внизу надо освободить несколько подвалов, чтобы по ним снова можно было пройти. Возьмёшься?"],"reach":["Спустись поглубже и посмотри, не осталось ли там старых кузниц. Мне очень хочется знать, кто работал до меня, а ты потом расскажешь.","Мне интересно, куда уходит эта шахта. Дойдёшь до нижних ходов? Я туда со своими плечами не пролезу.","Спустись, пожалуйста, глубже, чем ходят наши. Потом расскажешь, что там. Главное, вернись."],"named":["Есть внизу одна зверюга, которую люди уже называют по имени. Имя у неё плохое. Разберёшься с ней?","Одна большая тварь внизу сломала хороший клинок, а его хозяин еле унёс ноги. Найди её, пожалуйста. Клинка мне жальче, но ты никому не говори.","Про одну тварь внизу рассказывают страшное, и {@child} теперь ходит за мной и спрашивает, правда ли это. Сходи к ней. Мальчишке я скажу, что это было легко."],"fetch":["Ларец с резцами потерялся внизу, и мне его не хватает, как зуба. Поищешь? Я буду очень признателен, только вслух этого не скажу.","Без моих резцов я не могу поставить клеймо на работу. Ларец с ними остался где-то внизу. Принеси его, пожалуйста.","Пропал мой ларец с резцами, а {@merchant} клянётся, что он тут ни при чём. Поищи его внизу, пожалуйста. Он там, наверное, и лежит."],"room":["Есть внизу одно гнездо, и нечисть лезет из него прямо к нам. Мне за людей неспокойно. Закроешь его?","Одно логово там внизу никак не успокоится. Вычисти его, пожалуйста, и мне станет тише работаться.","В одном подвале устроили целое логово. Мне и тварей немного жалко, но людей жальче. Сходишь туда?"]},"done":["Ну, показывай. Вижу, что дело сделано, и руки у тебя на месте.","Сапоги целы, и ты при них. Значит, всё готово.","Работа сделана, и сделана хорошо. Я в работе понимаю.","Вот и всё, закончено. Я рад, что ты здесь. В смысле, что работа закончена."],"thanks":["Добрая работа. Держи, это твоё, и не спорь.","Вот теперь и горн веселее горит. Бери, не торгуйся, я всё равно не умею.","Спасибо. Я это редко говорю, поэтому запомни.","Спасибо. Хотел сказать ещё что-то доброе, но не умею. Держи.","Хорошие руки это делали, я вижу. Бери, пригодится.","Мне стало спокойнее. Возьми это, пока я не начал говорить о чувствах."],"boss":["{boss}, надо же! Об этом теперь весь посёлок говорит, и даже я говорю, хотя я молчун. Сходишь вниз ещё раз?","Значит, {boss} больше никого не обидит. Я очень рад. Там внизу есть ещё работа, возьмёшься?","{boss}! Мне рассказали, и я от радости уронил молот себе на ногу. Нога болит, а дело внизу осталось. Поможешь?","Говорят, {boss} теперь лежит тихо, и мне от этого хорошо. Внизу осталось ещё одно дело. Сходишь?"],"thing":"Ларец с резцами"},"enchanter":{"lines":[["Тише, пожалуйста. Руны не любят шума, а я тем более.","С кузнецом мы об этом говорили. Он кивнул и стукнул."],["Первое зачарование у меня всегда проходит спокойно.","Пятое я бы на твоём месте обсудила со своей совестью."],["Эта колба не для питья, дорогой человек.","Тот, кто выпил, теперь неплохо видит в темноте."],["Синее пламя означает, что всё идёт верно.","При жёлтом я обычно уже стою за дверью, и тебе советую."],["Я прочла о старых чарах всё, что уцелело.","Уцелело немного, зато читала я очень внимательно."],["Мне говорят, что я колдую, и я перестала спорить.","Считать дроби люди любят гораздо меньше, чем бояться."],["Если чары сорвутся, я очень тихо скажу об этом.","Кричать будешь ты, так у нас разделены обязанности."],["Торговец опять принёс мне амулет на проверку.","Это была крышка от кастрюли, и он уже успел её продать."],["Осколки, которые ты приносишь, помнят чужие жизни.","Пожалуйста, не клади их в один карман с сыром."],["{@child} просился ко мне в ученики.","Я попросила его помолчать один час. Он не смог."],["Кузнец большой и добрый, и я ему об этом не скажу.","У него и без того плечи не проходят в мою дверь."],["{@elder} забывает конец истории, когда ему выгодно.","Я записываю эти истории давно, и концов у них всё меньше."],["Говорю я тихо, потому что повторять мне не приходится.","Громко говорят те, кто не уверен в своих источниках."],["Покажи вещь, и я скажу, что ей подойдёт.","Хвалить заранее не стану, я видела твои сапоги."],["{@guard} один раз попросил у меня оберег.","Для себя он просить не стал. Он просил на всех."],["Вчера я ошиблась в расчёте.","Такое случается со мной раз в десять лет, поэтому молчи."],["Я записываю каждую руну, которую видела.","Одну мне видеть не стоило, и её я вывела особо чисто."],["{@town} стоит на шести других городах.","В каждом из них кто-то просил не шуметь, я это читала."],["В крипте спят старые чары, и будить их я не советую.","Ты всё равно разбудишь, так хотя бы вытри ноги."],["Мне нравится, что ты возвращаешься.","Я говорю это как учёная: мне нужны наблюдения."],["{@mason} спросил у меня, сколько звёзд на небе.","Я ответила точно. Он записал и снова сбился."],["Чтобы зачаровать вещь, нужны золото и осколки.","Ещё нужна я, но за это я беру уважением."],["{@porter} принёс мне ящик и не разбил ни одной колбы.","Я пересчитала трижды, потому что не поверила."],["Пламя в колбе ведёт себя прилично, пока я смотрю.","Как и большинство людей, насколько я могу судить."],["{@sweeper} приносит мне пирог и говорит, что я худая.","Я учёная женщина и ем его только из научного интереса."],["Кузнец однажды чихнул в моей мастерской.","Я до сих пор нахожу свои записи на крыше."],["Если вещь уже носит пять зачарований, больше не проси.","Вещь не выдержит, а я не захочу на это смотреть."],["Некоторые думают, что я ведьма.","Они говорят об этом шёпотом, и мне это нравится."],["Не трогай эту книгу, у неё плохое настроение.","Вчера она укусила торговца, и мы обе остались довольны."],["Внизу лежат старые палаты учёных.","Мне туда очень хочется. Тебе я этого не говорила."]]},"guard":{"lines":[["Стою на этом посту двадцать лет.","Пост цел, и я считаю это своей заслугой."],["Я считаю всех, кто спускается вниз.","И всех, кто поднимается. Второе мне нравится больше."],["Назад дорога всегда длиннее, чем кажется.","Мне рассказывают те, кто вернулся. Их я и слушаю."],["Последний приказ я получил двенадцать лет назад.","Там было написано: стоять. Поэтому я стою."],["Держи клинок наготове и ешь вовремя.","Вторую часть обычно забывают, я это вижу."],["Я не волнуюсь, я просто смотрю вниз.","Смотрю я туда раз сорок в день, и всё строго по службе."],["{@child} спросил, страшно ли стоять на посту.","Я ответил, что нет. Он пошёл и рассказал всем, что я вру."],["Мальчишка сегодня взял меня в плен.","Я сдался сразу, потому что у него была курица."],["{@porter} пробегает мимо поста сорок раз в день.","Я каждый раз спрашиваю пароль. Он отвечает: некогда."],["Мимо меня опять прошёл торговец с пустым мешком.","Я ему помахал. Через неделю за ним опять кто-то пойдёт."],["Я умею спать стоя, с открытыми глазами.","Когда кто-то внизу, я этого почему-то не умею."],["Ремень на левом сапоге у тебя ослаб.","Я заметил это по службе, мне положено замечать."],["{@sweeper} приносит мне суп и говорит, что я похудел.","Я тут двадцать лет и так и не научился отказываться."],["Мимо этого поста никто не пройдёт без разрешения.","Разрешаю я всем, но порядок есть порядок."],["Вижу, что ты опять собираешься вниз.","Возражать я не стану. Я просто стою здесь и не одобряю."],["Наш кузнец как-то встал рядом со мной на пост.","Он закрыл мне весь обзор. Я стерпел, он хороший."],["Чародейка говорит, что руны шумят, когда кто-то врёт.","Со мной они молчат, потому что я молчу."],["{@mason} сказал, что этот пост стоял и в прошлом городе.","Значит, я здесь дольше, чем думал."],["Огонь на площади не гаснет уже очень давно.","Я тоже не ухожу. Мы с ним в этом смысле коллеги."],["Старик у костра называет меня «молодой человек».","Мне это нравится, поэтому я с ним не спорю."],["Ночью внизу что-то стучало.","Я постучал в ответ. Теперь не знаю, правильно ли я сделал."],["Когда ты поднимаешься, я рисую в журнале кружок.","Кружок значит, что всё хорошо. Кружков у меня мало."],["Говорят, что враг никогда не спит.","Я его понимаю, мне тоже не спится."],["Плащ на мне тот же самый, что и двадцать лет назад.","Моль в нём тоже, кажется, та же."],["Мне однажды сказали, что у меня лицо ничего не выражает.","Я тогда очень сильно обиделся. Это было видно?"],["Я не люблю провожать людей вниз.","Поэтому я смотрю на небо и считаю до ста."],["Вниз ходят герои, а наверху стою я.","Кому-то надо быть здесь, когда они поднимутся."],["Кричать «караул» мне не приходилось ни разу.","Я иногда репетирую по ночам шёпотом."],["Как спалось? Я спрашиваю для отчёта.","Отчёт никто не читает, но ответить всё равно надо."],["{@town} сегодня спит спокойно.","Один я не сплю, за это мне и платят."]],"asks":{"kill":["Внизу развелось слишком много тварей, и мне это мешает спать. Сходи и убавь их, пожалуйста. Я потом проверю по звуку.","Я свой пост не брошу, а тебя никто не держит. Твари внизу обнаглели, и их надо проредить.","Снизу по ночам слышна возня, и {@sweeper} уже носит мне успокоительный чай. Разгони там всех, кто шумит."],"clear":["Внизу есть залы, куда никто из наших теперь не заходит. Мне это не нравится. Очисти несколько, чтобы было спокойнее.","За двадцать лет я так и не узнал, что творится в старых подвалах. Вычисти несколько, и я наконец перестану об этом думать.","Приказа у меня нет, поэтому я прошу по-человечески. Внизу надо освободить несколько комнат."],"reach":["Мне нужно знать, докуда можно дойти. Спустись поглубже и расскажи мне. Рапорт можно устный.","Дойди до мест, куда ещё никто из наших не добирался. Только потом обязательно вернись, иначе рапорт не сойдётся.","Посмотри, что там глубже, дорогой человек. Мне отсюда не видно, хотя я стараюсь уже двадцать лет."],"named":["Есть внизу одна тварь, чьё имя у нас уже говорят вполголоса. Мне такого на посту не надо. Найди её.","Про одну большую тварь мне докладывают каждый день. Мне надоело это слушать. Избавь меня от этих докладов, пожалуйста.","Там внизу ходит зверь, которого люди уже зовут по имени. Мне бы хотелось забыть это имя. Помоги."],"fetch":["Мой ларец с приказами уехал вниз на телеге и не вернулся. С тех пор мне никто ничего не приказывает. Найди его, пожалуйста.","Внизу лежит ларец с приказами, и без него я не знаю, всё ли делаю правильно. Двадцать лет не знаю. Принеси его.","Ларец с моими приказами кто-то унёс вниз, и я подозреваю торговца. Принеси ларец, а я пока продолжу подозревать."],"room":["Есть внизу одно логово, которое я хотел бы вычеркнуть из своих забот. Сходи туда и вычисти его.","В одном подвале свили гнездо. Мне его не достать, мне нельзя с поста. Тебе можно.","Одно логово внизу меня беспокоит. Меня многое беспокоит, но с этого можно начать."]},"done":["Вижу по глазам, что дело сделано. Я записал.","Дело сделано, и ты снова здесь. Это два кружка в журнале.","Вижу, что всё готово. Принимаю доклад, а молчание твоё считаю докладом.","Ты здесь, и руки с ногами у тебя на месте. Остальное мне уже не важно, но докладывай."],"thanks":["Одной заботой меньше, и теперь я волнуюсь за тебя по другому поводу. Держи.","Сегодня, может, и усну. Держи, это твоё.","От лица поста благодарю. Пост у нас это я.","Спасибо. Я не улыбаюсь, но знай, что внутри я улыбаюсь.","Бери и не спорь. Мне положено это выдать, я сам себе так приказал.","Хорошо. Запишу в журнал и ещё отдельно порадуюсь, когда никто не видит."],"boss":["{boss}. Хорошая работа. Спать я лучше не стал, потому что внизу есть ещё кое-что. Сходишь?","Значит, {boss} больше не поднимается. Я двадцать лет ждал этой новости и не знаю, что с ней делать. Пока я думаю, возьмёшься ещё за одно дело?","Мне доложили: {boss} больше никого не побеспокоит. Я рад, хотя по мне этого не видно. Внизу ещё есть работа, поможешь?","{boss} лежит, а ты стоишь. Такой порядок мне нравится. Там внизу ещё кое-что осталось, сходи, пожалуйста."],"thing":"Ларец с приказами"},"merchant":{"lines":["Заходи, дорогой человек! Золото не пахнет, я нюхал.","Эти вещи носили прошлые герои, и очень бережно, пока могли.","Торгуюсь я честно, особенно когда на меня смотрят.","Цена высокая, потому что я за этим лично лазил вниз.","Твой хлам я возьму, мне его даже немного жалко.","Этот свиток читал всего один человек. Он доволен, наверное.","Примерь шлем, дорогой человек. В нём ходила умная голова.","Зелье свежее, я лично видел, как оно булькало.","Скажу по секрету: вчера эта цена была выше.","{@guard} смотрит на меня подозрительно. Откуда он знает?","Кузнец сказал, что я ему должен. Я сказал, что подумаю.","Я всё думаю, что вниз больше не полезу. Потом вижу вазу.","{@elder} помнит день, когда я ушёл. Значит, волновался.","Зайди и после спуска. Мне просто нужны покупатели, не думай.","Отдать мне не жалко, мне жалко отдать дёшево.","Эту вещь я нашёл сам, и лежала она почти без присмотра.","Цена твёрдая, как мои принципы, то есть договоримся.","Покупай, пока мы оба не передумали.","За такую цену я сам себе завидую.","Это старинная вещь, ей уже почти неделя.","{@enchanter} велела мне вести себя тише. Я обсчитываю шёпотом.","{@child} хотел продать мне курицу. Курица была не его.","{@sweeper} гоняет меня метлой от порога, как родного.","Я ведь тоже переживаю, когда ты внизу. За долг, конечно.","Подходи ближе, у меня нет от тебя секретов, кроме цены.","Говорят, что жадность губит людей. Меня она пока кормит.","Мои покупатели всегда возвращаются, хотя бы поругаться.","Честно скажу: эту штуку я и сам не понимаю. Возьмёшь?","Сегодня торгую с настроением, а настроение у меня дорогое.","У каждой вещи здесь есть история, я их сам сочиняю."],"hit":["Эй! За удары у меня отдельная цена!","Мечом скидку не выбьешь, я проверял на других!","Осторожнее, дорогой человек, я тут самый хрупкий товар!","Кому ты продашь свой хлам, если прибьёшь меня?","Это я запишу на твой счёт, и запишу крупно!","Если это торг, то я уступаю очень медленно!","Прекрати, я и так всем должен!","Бить продавца плохая примета, цены от этого растут!"],"calls":["Зелья, свитки, всякая старина, подходи!","Эй, дорогой человек, тебя-то я и ждал!","Подходи скорее, пока цены не проснулись!","Иди сюда, дорогой человек, я сегодня добрый!","Такого внизу не найдёшь! Там я уже всё забрал!","Эй, не проходи мимо, я же всё вижу!","Свежие зелья! Ну почти свежие, зато с характером!","Кому свиток на дорожку? Подходи, пока я не передумал!","Подойди хоть поругаться, я сегодня в голосе!","Для тебя особая цена! Она у меня для всех особая!","Эй, кто там идёт с полными карманами?","Иду на уступки! Уступать пока не начал, но иду!"],"freed":["Спасибо, дорогой человек! Счёт за клетку пришлю отдельно!","Я не застрял, я изучал клетку изнутри! Бегу наверх!","Меня тут никто не видел! Бегу наверх открывать лавку!"]},"porter":{"lines":[["Не стой на дороге, я не вижу ничего из-за ящика!","Если ты не ящик, отойди, пожалуйста, влево."],["Мне платят поштучно, а спина считает по весу.","Вот и спорим с ней каждый вечер, кто из нас прав."],["{@merchant} велел нести это бережно и не открывать.","А оно внутри шевелится, и я стараюсь идти бережно."],["{@smith} как-то молча донёс мой ящик до самой лавки.","Я сказал спасибо, а он сделал вид, что это не он."],["Говорят, {@town} стоит на шести других городах.","И ни один из них ни разу не помог мне с ящиком."],["Вчера я нёс большое зеркало и испугался какого-то типа.","Он был красный и шатался, и мне стало его жалко."],["{@sweeper} ругает меня за следы на её дорожке.","А потом догоняет и суёт мне варежки."],["{@child} просит прокатить его на ящике.","Я сказал, что это стоит монету, и он принёс курицу."],["Я бы спустился с тобой, честное слово, да руки заняты.","Они у меня заняты уже лет пять, если считать честно."],["У меня шнурок развязался ещё во вторник.","Завяжу, когда поставлю ящик, то есть примерно к осени."],["{@guard} каждое утро спрашивает, что у меня в ящике.","Я отвечаю, что ящик, и он кивает. Мы уже почти дружим."],["Мне однажды приснилось, что я иду с пустыми руками.","Проснулся в холодном поту и пошёл проверять ящики."],["Будь там осторожнее, пожалуйста, внизу темно.","Я тут ящик уронил на ровном месте, при полном свете."],["{@enchanter} велела нести склянки без единого звука.","Я перестал пыхтеть и чуть не умер на середине улицы."],["{@mason} зовёт меня таскать камни и говорит: их немного.","Он их сосчитать не может, откуда ему знать!"],["Вот этот мешок я несу уже третий день.","Забыл, кому, а спрашивать теперь уже неудобно."],["У меня спина болит только по утрам и вечерам.","Днём мне некогда её слушать."],["Говорят, внизу золото лежит прямо на полу.","Я сразу подумал, кому его потом придётся носить."],["У тебя такая лёгкая походка, просто завидно!","Это потому, что ты не несёшь бочку, правда?"],["{@elder} говорит, что тоже когда-то носил камни.","Только не может вспомнить, в каком веке это было."],["Подержи-ка минутку этот сундук, мне надо чихнуть.","Шучу, я уже чихнул, а сундук по-прежнему на мне."],["Когда ты спускаешься, я всегда смотрю тебе вслед.","Ящик при этом падает, но ты, главное, возвращайся."],["{@merchant} послал меня с запиской на другой конец улицы.","Записка была мне: он заплатит на той неделе."],["Знаешь, что самое приятное в работе носильщика?","Ставить ящик на пол. Других радостей я пока не нашёл."],["У меня руки стали длиннее, честное слово!","Я уже могу почесать колено, не наклоняясь."],["Я считаю, что дома надо ставить поближе друг к другу.","Особенно тот, куда идёт ящик, и тот, откуда он идёт."],["Вчера я пробежал всю улицу с бочкой на плече.","Оказалось, бочка пустая, а я ещё всем хвастался."],["Ты слышишь, как я дышу? Это я так разговариваю.","А молчу я обычно чуть громче."],["Кто придумал лестницы, тот никогда не носил сундуков.","А кто придумал сундуки, тот, похоже, не видел лестниц."],["Если вдруг станет тяжело там, внизу, вспомни про меня.","Тебе сразу станет легче, ведь ты хотя бы без шкафа."]],"asks":{"kill":["Слушай, там внизу столько всякой нечисти, что склад трясётся от беготни. Займись ею, пожалуйста! У меня ящики падают с полок, и каждый раз именно на меня.","Каждое чудовище, что останется внизу, однажды поднимется сюда. А я тут хожу с бочкой и увернуться не смогу. Сходи и побей их, пока они не поднялись, хорошо?","Чудовища скребутся у нас под полом так, что мне ночью страшно ставить ящик. Убавь их немного, сделай доброе дело."],"clear":["{@merchant} задумал устроить внизу склад, а таскать туда придётся мне. Очисти там комнаты от всякой живности, пожалуйста, мне ещё жить хочется.","Сверху я слышу, как они топают по комнатам, и сбиваюсь с шага. Выгони их всех оттуда, хорошо?","Я тебе сейчас всё объясню, только отдышусь... Нет, не отдышусь. Комнаты внизу полны тварей, вымети их оттуда!"],"reach":["Тут один человек заказал доставку куда-то вниз, а докуда идут ступени, никто не знает. Спустись и посмотри, пожалуйста, мне надо прикинуть, сколько брать.","Мы с каменотёсом поспорили о шахте. Он говорит, что она глубокая, а я говорю, что очень глубокая. Спустись и рассуди нас, пожалуйста.","Три дня назад у меня укатился бочонок, и ночью я всё ещё слышу, как он катится вниз. Спустись и посмотри, докуда он докатился."],"named":["Там внизу завелась тварь, у которой есть своё прозвище. Простым зверям прозвищ не дают, так что дело серьёзное. Найди её и разберись, пожалуйста.","Говорят, та зверюга за ночь утаскивает больше, чем я за неделю. Я такого соперника не потерплю. Сходи и проучи её, ладно?","Про эту тварь {@guard} говорит только шёпотом, а он и про пожар говорил обычным голосом. Найди её, пока он совсем не замолчал."],"fetch":["Я уронил в шахту ларец с накладными. Теперь {@merchant} улыбается и говорит, что ничего мне не должен. Найди ларец, пожалуйста, пока он не начал напевать.","Всё, что я носил за год, записано в одном ларце, а ларец теперь внизу. Принеси его, иначе выходит, что я весь год просто гулял с ящиками.","Это очень лёгкий ларец, я нёс его одним пальцем и поэтому уронил. Принеси его, пожалуйста. Больше лёгких вещей я в руки не возьму."],"room":["Внизу есть логово, и пахнет оттуда так, что я дышу ртом. А я и так дышу ртом, и теперь мне вдвойне тяжело. Разгони их, пожалуйста!","Логово устроили как раз там, где удобно было бы идти с грузом. Я против них лично ничего не имею, но ты их разгони, пожалуйста.","Кто-то устроил себе внизу целое логово и живёт там, ни разу ничего не перенося. Обидно же! Выгони их оттуда, будь другом."]},"done":["Ого, неужели готово? Погоди, сейчас поставлю ящик, чтобы удивиться как следует!","Я всем уже рассказал, что ты справишься, и теперь даже не придётся врать.","Ну вот и всё! Так быстро я даже мешок не успеваю донести.","Готово? А я тут как раз отдыхаю, вот только ящик пока не поставил."],"thanks":["Вот спасибо! Возьми, я это нёс как раз для тебя.","Спасибо тебе от меня и от моей спины. Спина бы сама сказала, но она уже легла.","Выручаешь, дорогой человек! Бери, пока у меня есть свободная рука.","Благодарю! Ты даже не представляешь, как приятно, когда тяжёлое несёт кто-то другой.","Спасибо! Я сегодня впервые за неделю улыбнулся и ничего при этом не уронил. Возьми вот.","От всей души спасибо! Я бы тебя обнял, да мне нечем. Вот, возьми."],"boss":["{boss} больше никого не потревожит? Я от радости чуть ящик не уронил! Раз ты такое можешь, возьмёшь и моё дело?","Погоди, это правда, что {boss} теперь лежит и не встаёт? Я бы тоже полежал. А пока у меня для тебя есть работа, если не откажешь.","Теперь {boss} никого не пугает! Я всю дорогу бежал тебе это сказать, хотя ты и так знаешь. Заодно попрошу об одной мелочи.","И сколько же весит {boss}, как думаешь? Нести такое я бы не взялся. А вот маленькая просьба к тебе у меня есть."],"thing":"Ларец с накладными"},"sweeper":{"lines":[["Опять весь порог в пепле, я же только подмела!","Ну кто так ходит? Хотя ты, золотце, ступай, ступай."],["Я мету эту площадь столько лет, что она стала ниже.","Ещё лет двести, и мы выйдем к соседям снизу."],["Весь пепел летит от костра, а у костра сидит {@elder}.","Я прошу его хоть чихать в другую сторону, а он смеётся."],["Ты хоть поесть успеваешь там, внизу?","Молчишь, значит, нет. Вот так и знала, что не ешь."],["Ноги вытирай, золотце, там внизу сплошная грязь.","Там-то ладно, там никто не убирает, а тут я."],["Я ругаю весь город, потому что всех люблю.","Тебя тоже могу отругать, ты только скажи когда."],["{@porter} опять бегает без шапки в такой ветер.","Простынет, а кто мне потом золу таскать будет?"],["{@guard} двадцать лет стоит на посту и не ест горячего.","Я ношу ему суп, а он отвечает: не положено, и съедает."],["{@child} опять притащил курицу прямо на мой порог.","Я уже и курицу вымела, а она всё равно вернулась."],["Метла у меня уже четвёртая, а рука всё та же.","Рука, правда, скрипит, а метла нет."],["{@smith} такой громадный, а плачет, когда режет лук.","А потом говорит, что это искра в глаз попала."],["{@enchanter} смотрит на меня так, будто я пыль.","Ничего, пыль я знаю, с пылью я как-нибудь справлюсь."],["Когда пойдёшь вниз, оденься потеплее, там сквозит.","И не спорь со мной, я уже сказала, что там сквозит."],["Говорят, что этот город строят уже седьмой раз.","И ни разу никто не подумал за собой подмести."],["Бывает, найду в пепле пуговицу и сижу, думаю.","Чья-то же это пуговица, чья-то мать её пришивала."],["{@merchant} продал мне новую метлу втридорога.","Я узнала её потом: это моя старая, он её просто помыл."],["Придумали тоже, пешком в темноту за чужими делами!","Ты только не обижайся, душа моя, это я от волнения."],["Я знаю, кто в городе с кем не разговаривает.","Мирю я их тоже сама, только они об этом пока не знают."],["{@mason} всё считает камни и забывает поесть.","Я ему сказала: считай обеды, их меньше, не собьёшься."],["Ох, спина моя, спина, а ведь ещё только утро.","Хотя нет, уже вечер. Вот я и до вечера дожила."],["Я таких, как ты, перевидала немало, дорогой человек.","И всех до единого просила беречь себя, и тебя прошу."],["Ты там внизу, пожалуйста, не лезь вперёд всех.","Никто не обидится, а я так и вовсе спасибо скажу."],["Моя метла говорит мне больше, чем все соседи.","По золе у порога я вижу, кто ночью не спал."],["Огонь горит веками, а пепел всё мой да мой.","Хоть бы кто спросил, куда я всё это деваю."],["Вот этот уголок я подметаю особенно аккуратно.","Там раньше сидела одна собака, хорошая была собака."],["Когда ты вернёшься, я тебя сразу заругаю за грязь.","Так что ты, пожалуйста, вернись, я уже приготовилась."],["{@child} сказал, что станет героем и купит мне дворец.","Я спросила, кто будет его мести, и он задумался."],["Ты на меня не смотри так, я не сержусь.","Это у меня лицо такое с тех пор, как изобрели золу."],["Все думают, что пол сам становится чистым.","А я сорок лет поддерживаю в городе это заблуждение."],["Говорят, та шахта тянется вниз без конца.","И ведь нигде там никто не метёт, сердце разрывается."]],"asks":{"kill":["Там внизу развелось столько всякой дряни, что снизу пыль идёт столбом. Сходи, золотце, поубавь их, а то я до вечера не домету.","От этой нечисти один сор и беспокойство, дорогой человек. Поубавь их там, а я весь день буду за тебя волноваться, это я умею.","Я полвека выметаю то, что лезет снизу, и ни разу никто не спросил, не устала ли я. Сходи и побей этих тварей, душа моя, пока они опять не полезли."],"clear":["Комната считается чистой, когда в ней никого нет и ничего не шуршит. Сходи и наведи там порядок, как я тебя учила.","Если бы я могла спуститься туда с метлой, они бы у меня давно бежали до самого низа. Колени не пускают, так что иди ты, душа моя, и выметай их из комнат.","Пройдись, золотце, по тем комнатам и выгони оттуда всех до единого. За тобой хоть потом чисто будет, не то что за другими."],"reach":["Хочу знать, докуда снизу идёт этот пепел. Спустись и посмотри, золотце, и потом скажи мне правду, даже если там опять кто-то не подметает.","{@guard} говорит, что снизу тянет сквозняком, а мне весь пепел несёт обратно на площадь. Спустись поглубже и посмотри, откуда дует.","Кто-то там внизу стучит по ночам, и я из-за него не сплю. Спустись, душа моя, и посмотри, докуда идёт этот стук. А ругать его я потом буду сама."],"named":["Про эту тварь рассказывают те, кто успел от неё убежать, и рассказывают с удовольствием. Найди её, душа моя, только не геройствуй сверх меры.","Я таких наглых зверей ещё не видала, хотя я вообще никаких не видала и видеть не хочу. Сходи и разберись с ней, золотце, раз уж никого храбрее у нас нет.","Про эту зверюгу {@porter} рассказывал так, что уронил ящик. Он у меня нервный. Найди её и поговори с ней как следует, хорошо?"],"fetch":["Медальон мой серебряный я вымела в шахту вместе с пеплом. Сама вымела, сама и плачу. Поищи его, золотце, он наверняка там уже весь в пыли.","В медальоне у меня портрет. Чей портрет, это не твоё дело, золотце, а вот найти его твоё. И внутрь, пожалуйста, не заглядывай.","Серебро, конечно, ерунда, мне оно и не нужно. Только я без него на улицу не выходила, а тут вышла и сама не своя. Принеси его, душа моя."],"room":["Там внизу кто-то завёл себе логово и не убирает за собой годами. Я об этом и слышать спокойно не могу! Иди и выгони их оттуда, золотце.","Они там называют это логовом, а я называю это беспорядком. Сходи и разгони эту компанию, душа моя.","Мне рассказали про одно логово, и теперь я всю ночь думаю, сколько там грязи. Избавь старую женщину от этих мыслей, дорогой человек."]},"done":["Вот и хорошо, вот и ладно. Иди сюда, дай посмотрю, всё ли у тебя на месте.","Сделано? А я уже вся извелась. Ну, показывай руки, ноги и совесть.","Ну наконец-то. Я тут трижды подмела, пока ждала, а могла бы и один раз.","Гляжу на тебя и вижу: дело сделано, а ноги опять не вытерты. Одно радует, другое огорчает."],"thanks":["Спасибо тебе, золотце. Возьми вот, и не спорь со старой женщиной.","Пусть у тебя всегда будут чистые дороги и тёплые ноги. Возьми вот это, да не отказывайся.","Ох, уважаешь ты старуху. Возьми, пока я не расплакалась и не намочила пол.","Вот спасибо! Я буду хвастаться тобой весь вечер, но тебе об этом не скажу.","Спасибо, дорогой человек. Теперь у меня на одну заботу меньше, а их, поверь, и так осталось целое ведро.","Молодец, золотце, ведь можешь, когда хочешь. Держи, и шапку не забывай."],"boss":["{boss} больше никого не тронет? Ну надо же, а ведь я только вчера говорила, что с тобой надо быть поласковее. Сходи ещё разок, золотце, по моей просьбе.","Слышала я, что {boss} теперь спокойно лежит и никого не ест. Вот и славно, а там ещё кое-кто шумит. Поможешь старой женщине?","Неужели {boss} больше никому не помешает? А у меня как раз нашлось одно дело поменьше, золотце, только ты теперь ходи там осторожнее.","Подумать только, даже {boss} теперь не встанет с пола. Жаль, что там никто после этого не подмёл. Возьмёшься ещё за одно дело, душа моя?"],"thing":"Серебряный медальон"},"child":{"lines":[["А ты правда ходишь туда, вниз? Прямо ногами?","А там страшно? А можно я с тобой? А курицу можно?"],["Когда я вырасту, я тоже пойду вниз!","Я уже вырос на вот столечко, смотри!"],["У меня есть меч, и он настоящий, он из ветки!","Это очень редкая ветка, другой такой нет!"],["Мою курицу зовут Королева Гроза, и она меня слушается.","Вчера она послушалась и клюнула меня в ногу."],["{@guard} не пускает меня вниз, потому что я маленький.","А я ему сказал, что завтра буду больше!"],["Я научил курицу ходить строем!","Ну, пока она ходит только за мной и только за зерном."],["{@sweeper} сказала, что оторвёт мне уши, если я полезу вниз.","Но потом дала пряник, так что это не считается."],["Покажи, как ты бьёшь! Нет, лучше я тебе покажу!","Извини, это был твой сапог, я думал, это чудовище."],["Я тренируюсь, смотри: я могу не моргать очень долго!","Сейчас не считается, мне в глаз попало куриное перо."],["Хочешь, я буду твоим помощником, а ты моим героем?","Или давай наоборот, я согласен!"],["{@elder} разрешил мне подбросить полено в огонь!","Он сказал, что у меня получается, и странно посмотрел."],["А чудовища едят кур?","Скажи им, что мои куры с тобой. Ну пожалуйста!"],["У меня есть шрам! Вот тут! Его надо искать при свете!","Это Королева Гроза клюнула меня в битве за зерно."],["Я нашёл под крыльцом настоящий камень из старого города!","{@mason} посмотрел и сказал, что это картошка."],["Я считаю до ста, и меня никто не может остановить!","Только {@mason} просил больше не считать рядом с ним."],["Я сегодня победил три лужи и одну крапиву!","Крапива, кстати, дала сдачи, но я не плакал, честно."],["Когда я вырасту, у меня будет прозвище, как у чудовищ!","Меня будут звать Куриный Рыцарь, и все будут бояться!"],["А тебе страшно бывает? Мне вот никогда не бывает!","Только ночью бывает и когда курица смотрит молча."],["{@porter} катал меня на ящике, и я был капитаном!","Потом ящик донесли, и я перестал быть капитаном."],["Дай мне меч подержать, ну на одну капельку!","Я его верну, честно-честно, я просто немного побегаю."],["{@smith} сделал мне ножик из гвоздя, только ножик тупой.","Он сказал, что им можно резать только воздух, и покраснел."],["Я видел, как ты уходишь вниз, и смотрел долго-долго!","Потом мне стало скучно, и я посмотрел на курицу."],["Когда ты вернёшься, ты мне всё-всё расскажешь?","Я уже буду не спать. Я уже сейчас начал не спать!"],["{@merchant} сказал, что продаст мне волшебное яйцо.","А оно похоже на яйцо от моей курицы, только дороже."],["Я буду героем, а потом ещё и королём кур!","Я уже почти стал, осталось договориться с курами."],["А у тебя есть секретный удар? У меня есть!","Я его никому не показываю, даже себе."],["{@enchanter} сказала, что я слишком громкий для магии.","Я спросил, можно ли колдовать криком, и она закрыла дверь."],["У меня болел зуб, и я не плакал, потому что я герой.","Потом {@sweeper} его вытащила, и вот тогда я заплакал."],["Куры почти не умеют летать, а у меня почти получается.","Я спрыгнул с бочки и летел целых один раз!"],["А ты вернёшься? Ты обязательно возвращайся, ладно?","Мне ещё надо показать тебе одну очень важную курицу."]],"asks":{"kill":["Слушай, мы с курами решили, что чудовищ внизу слишком много. Побей их, ладно? Куры сами не могут, у них сегодня дела.","Я всем сказал, что ты победишь вообще всех! Теперь придётся победить хотя бы сколько-нибудь, а то мне никто не поверит.","Давай так: ты побеждаешь чудовищ, а я считаю их на заборе углём. Я умею считать до ста и ещё немножко! Это будет самый лучший забор."],"clear":["Там внизу есть комнаты, в которых живут чудовища, а им там жить нельзя! Выгони их, потому что я потом хочу там играть, когда вырасту.","Мне нужны пустые комнаты для моего войска. В войске пока четыре курицы, но они любят простор! Очисти комнаты, пожалуйста!","{@sweeper} говорит, что после героя всегда остаётся мусор, а я говорю, что после героя всегда остаётся победа! Иди очисть там всё, и мы узнаем, кто прав."],"reach":["А спустись, пожалуйста, ещё глубже, чем все! Потом расскажешь мне, что там, а я расскажу всем, что это я тебя послал.","Королева Гроза вчера ушла в шахту и вернулась через час. Я думаю, она там что-то видела. Спустись и проверь, потому что она не говорит!","Я хочу знать, есть ли внизу дно. {@guard} говорит, что есть, а {@elder} посмотрел на меня и ничего не сказал. Сходи и проверь, потому что теперь мне интересно."],"named":["Там внизу живёт чудовище с настоящим прозвищем! Я тоже хочу прозвище, а у него оно есть, это нечестно! Победи его, и тогда его прозвище будет ничьё.","Это самое страшное чудовище! Я его не видел, но я так думаю! Победи его и потом расскажи мне, какой у него был голос.","{@merchant} сказал, что от этого чудовища не убежать, а я сказал, что ты и не будешь убегать. Иди скорее, потому что я уже поспорил на курицу!"],"fetch":["Я поменял мою лошадку на настоящий зуб дракона. Зуб оказался козий, а {@merchant} уже ушёл с лошадкой вниз. Найди её, пожалуйста!","Её зовут Молния, она деревянная и очень быстрая. Она убежала в шахту, потому что я её туда уронил. Принеси её, только скажи ей, что я не нарочно!","Моя лошадка там внизу совсем одна, и ей страшно, хотя она деревянная. Найди её, пожалуйста. Я никому не скажу, что я плакал, и ты тоже не говори."],"room":["Внизу есть настоящее логово! Вот бы поселить там кур, но сначала надо выгнать тех, кто там живёт. Это твоя работа, а кур я возьму на себя!","Я построил логово под крыльцом, но у чудовищ логово лучше, и мне обидно. Разгони их, пусть живут как все, без логова!","Там внизу кто-то устроил логово и никого не позвал! Я бы всё равно не пошёл, потому что занят, но мне обидно. Разгони их там, ладно?"]},"done":["Это правда?! Всё уже готово?! Покажи, покажи, покажи!","Я так и знал! Я всем говорил, что ты сможешь, и особенно курицам!","Ура! Можно я теперь скажу всем, что это мы вместе? Ну хотя бы что я стоял рядом!","Это было лучше всего на свете, это я тебе как будущий герой говорю!"],"thanks":["Ура! Спасибо! Это тебе, только не потеряй, это очень ценное!","Спасибо! Я хотел отдать тебе курицу, но она отказалась, так что вот это.","Ух ты! Я расскажу всем, даже тем, кто уже знает! Держи!","Ты лучше всех на свете, кроме Королевы Грозы, но она курица и не считается. Держи!","Спасибо большое! Когда я стану героем, я тоже кому-нибудь помогу, а пока возьми вот это.","Я теперь почти герой, потому что я тебя знаю! Возьми, это очень нужная вещь, наверное."],"boss":["{boss} теперь ничего не может?! Вот это да! А я тоже знаю одно чудовище, только маленькое, и там нужна твоя помощь!","Все говорят, что {boss} больше не встанет! Можно я всем скажу, что видел это? А маленькое дело возьмёшь?","Ого-го! {boss} больше никогда никого не укусит, правильно? Тогда у меня как раз есть другое дело, и оно тоже страшное, честно!","{boss} и моя курица, кто сильнее, как думаешь? Теперь-то, конечно, курица! Сходи, пожалуйста, ещё на одно дело."],"thing":"Деревянная лошадка"},"mason":{"lines":[["Двести семь, двести восемь... Добрый день.","А добрый день идёт в счёт или нет?"],["Этот блок я уже тесал, вот моя зарубка на углу.","Когда я её поставил, никак не могу припомнить."],["Камень не спешит, и я за ним стараюсь не спешить.","Мы с ним так и до обеда не дошли, зато договорились."],["На этом камне кто-то нацарапал имя своей жены.","Я теперь кладу его лицом внутрь, пусть ей будет теплее."],["Говорят, наш город седьмой по счёту.","Если так, то я бы и шестой пересчитал, на всякий случай."],["Стену надо класть так, чтобы стояла после тебя.","А что будет после тебя, это стена сама разберётся."],["Вчера я насчитал триста камней, сегодня двести девяносто.","Никто не приходил, значит, камни решили сами."],["Этот порог истёрли чьи-то ноги, а чьи, теперь не узнать.","Кто-то вот так же каждый день шёл домой и не думал об этом."],["Шахта отдаёт нам камни, а мы строим из них дома.","Потом шахта получает их обратно, и всё идёт сначала."],["Мне нравится, когда блок садится на место со звуком.","Вот такой тихий стук, будто кто-то вернулся домой."],["{@elder} сказал, что этот камень раньше был пекарней.","Я постоял рядом и действительно есть захотел."],["Если сбиваешься со счёта, начни с того, что помнишь.","Я помню, что камни были, и с этого начинаю."],["{@sweeper} просит не пылить, и я стараюсь пылить тише.","Она говорит, что пыль у меня неправильная, слишком белая."],["Иногда я думаю, что это камни считают меня.","У них, наверное, тоже всё сбивается на мне одном."],["Вон там лежит кусок колонны, у него есть завиток.","На завиток ушла целая неделя, а теперь на нём сидит курица."],["Хороший угол держит весь дом и ничего об этом не говорит.","Я бы и сам хотел таким быть, но я разговорчивый."],["Говорят, внизу целые улицы из такого же камня.","Выходит, соседи у нас снизу, просто мы редко заходим."],["Кто-нибудь однажды построит дом у нас на крыше.","Хочется оставить ему ровную крышу, чтобы было удобно."],["{@smith} принёс мне новый резец и молча положил рядом.","Я так и не понял, подарок это или он просто застеснялся."],["Считать камни надо утром, пока они не разошлись.","К вечеру половина уже стоит в стене и притворяется."],["Ты не мешаешь, стой тут, сколько хочешь.","Когда рядом кто-то стоит, камень идёт веселее."],["Этот камень треснул, и я всё думаю, кто его обидел.","Может, ему просто надоело держать всё на себе."],["Шесть городов ушли под землю, а камни остались.","Считать их я уже не берусь, а руками всё равно глажу."],["{@porter} говорит, что камни становятся тяжелее.","Я прикинул: камни те же, просто день уже длинный."],["Меня спросили, зачем я считаю, раз всё равно сбиваюсь.","А я и не считаю, я просто здороваюсь с каждым."],["Бывает, кладёшь стену весь день, а она выходит кривая.","Зато кривая моя, и другой такой ни у кого нет."],["Вот этот блок тёплый, хотя солнца тут и не было.","Наверное, его просто кто-то долго держал."],["{@guard} тоже стоит на одном месте двадцать лет.","Я ему говорю: из тебя вышла бы хорошая колонна."],["Всегда остаётся один лишний камень, куда ни положи.","Я его каждый вечер уношу домой и ставлю у двери."],["Ну вот, досчитал до конца, и опять один не сходится.","Это, наверное, тот, на котором я сейчас стою."]]},"keeper":{"lines":[["Я сюда не приходил. Первые телеги застали меня у костра.","Я спросил, почему так долго, и меня приняли за местного."],["Садись. Этому костру больше лет, чем нашей улице.","А улице у нас, между прочим, две тысячи лет."],["{@sweeper} всё утро ругает золу на чём свет стоит.","Я, знаешь, всякий раз принимаю это на свой счёт."],["{@merchant} покупает старину и платит за неё медью.","Ко мне он тоже приценивался. Дал бы два медяка."],["Огонь надо кормить понемногу, как старого пса.","Дашь сразу много, и он потом неделю на тебя дуется."],["Я помню всех, кто спускался, по сапогам.","Лица путаю, а сапоги у тебя хорошие, я их запомню."],["У меня есть для тебя мудрый совет, самый главный.","Подожди, дрова подброшу. Так о чём мы говорили?"],["{@child} уверяет, что костёр с ним разговаривает.","Со мной он молчит уже очень давно. Я немного ревную."],["{@guard} каждую ночь проверяет, горит ли костёр.","Говорит, это по службе. Потом сидит рядом до утра."],["{@smith} вчера принёс мне подкову на счастье.","Покраснел, сунул в руки и убежал. Такой большой человек."],["{@enchanter} поправляет меня, когда я путаю даты.","Я там стоял, а она про это читала. Спорим с удовольствием."],["{@mason} нашёл камень, который тесал мой знакомый.","Я узнал работу: кривовато, зато от души."],["{@porter} пробежал мимо с мешком и спросил, как дела.","Я вдохнул, чтобы ответить, а он уже вернулся с другим."],["Тут уже шесть раз стоял город, на одном и том же месте.","Седьмой раз место тоже выбирали очень тщательно."],["Огонь выносили наверх шесть раз. Один раз несли в шапке.","Шапку жалко. Хорошая была шапка."],["Ночью снизу что-то стучит, ровно и без устали.","Я волнуюсь за ту ночь, когда оно вдруг перестанет."],["Люди, которые строили этот посёлок, думали о детях.","Люди, которые строили тот, что под ним, думали о том же."],["Осколок, который ты приносишь, это чья-то память.","Может, про пирог. Память обычно бывает про пирог."],["Я вовсе не старый. Я просто очень давно начал.","Кости со мной не согласны, но с ними мы давно не говорим."],["Когда-то я думал, что скоро всё это брошу и уйду.","Потом подбросил дров и решил ещё немного подождать."],["Ты ешь хоть что-нибудь? Внизу тебя никто не накормит.","Хотя там, говорят, кто-то накрывает на стол. Не садись."],["Я тебе не рассказывал, кто первым принёс сюда огонь?","Рассказывал? А что я сказал? Мне было бы интересно."],["Огню всё равно, кто к нему подсел. Это его лучшее качество.","Мне не всё равно, но мне и лет поменьше, чем ему."],["{@child} просится посидеть у огня вместо меня.","Я разрешил. Через пять минут он заснул с палкой в руке."],["Снизу тянет сыростью и чужими подвалами.","А {@sweeper} считает, что это я опять не проветрил."],["В молодости я тоже рвался вниз, представь себе.","Молодость была давно, и низа тогда было поменьше."],["Ты, главное, возвращайся. Я привык, что ты возвращаешься.","Отвыкать в моём возрасте приходится очень долго."],["Говорят, я сижу и думаю о вечном.","Я думаю об обеде, просто с очень серьёзным лицом."],["Объявление я писал сам и сделал там ошибку.","Написал «вернётесь». Не знаю, зачем я это пообещал."],["Вещи в сундуке помнят больше героев, чем я.","И пахнут ими, если честно, тоже."]],"asks":{"kill":["Под нами опять развелось тварей, и от их возни у меня трясётся котелок. Проредишь их немного?","Внизу собралась целая толпа незваных жильцов, и шумят они уже громче нас. Сходи и разгони их, а то мы сами себя не слышим.","Снизу лезет всякая нечисть, и {@guard} опять не спит. Поубавь её, пожалуйста, пусть он хоть одну ночь поспит."],"clear":["Там внизу есть комнаты, куда я хотел бы когда-нибудь заглянуть ещё раз. Выгони оттуда постояльцев, сделай милость.","Кто-то занял старые дома внизу и даже не спросил разрешения. Очисти их от этой публики, а я пока подброшу дров.","Комнаты внизу набиты битком, как лавка в базарный день. Проветри их мечом или чем у тебя там."],"reach":["Мне нужно знать, как там глубже. Спустись, посмотри и расскажи старику, пока он помнит, о чём спрашивал.","Говорят, внизу есть места, куда давно никто не доходит. Доберись до них, мне любопытно, стоят ли они ещё.","Я там когда-то бывал, но с тех пор всё сильно съехало вниз. Спустись и расскажи мне, что там теперь."],"named":["Внизу завелась одна тварь с собственным прозвищем. Если у зверя есть прозвище, значит, он уже кого-то съел. Найди его.","Про одного зверя внизу рассказывают такое, что {@child} перестал спать. Покончи с ним, пока мальчик не пошёл туда сам.","У того чудища внизу такое прозвище, что мне неловко произносить его у огня. Найди его и избавь нас от этого слова."],"fetch":["Я обронил внизу одну вещицу, ещё когда там было светло. Принеси её, пожалуйста, мне её очень не хватает.","Есть там одна вещь, которую мне хочется снова подержать в руках. Поищи её, а я пока вспомню, зачем она была нужна.","Вещь, которую я ищу, лежит внизу с тех пор, как там жили люди. Принеси её наверх, пока за ней не полез {@merchant}."],"room":["Внизу есть одно логово, откуда по ночам тянет дурным духом. Сходи и вычисти его до последнего жильца.","В одной норе там поселились те, кто очень мешает мне спать. Разгони их, и мы с огнём наконец выспимся.","Там внизу есть логово, куда даже мыши не заходят. Загляни туда с оружием и убери всех, кто там живёт."]},"done":["Ну вот, а я уже придумывал, что скажу огню, если ты задержишься.","Дело сделано? Вот и хорошо. Я как раз успел забыть, о чём просил, но сейчас вспомню.","{@sweeper} поставила медяк, что ты вернёшься, а я поставил на то же самое. Теперь нам обоим некому платить.","Огонь всегда трещит громче, когда к нему подходит человек с хорошей новостью. Рассказывай, я слушаю."],"thanks":["Спасибо тебе. Вот, возьми, это лежало у меня для хорошего человека.","Давно меня так не радовали. Бери, пока я помню, что собирался дать.","Огонь тебе кланяется, а я ему помогаю. Возьми, это от нас обоих.","Ты меня очень выручаешь, дорогой человек. Вот твоя награда, и не вздумай отказываться.","{@merchant} сказал бы, что я переплачиваю, поэтому ему мы ничего не скажем. Держи.","Я тебе должен, а долги я помню лучше, чем имена. Вот, держи пока это."],"boss":["{boss} больше никому не мешает спать, и за это тебе от меня поклон. Раз ты сегодня в ударе, у меня есть ещё одно дело.","Значит, {boss} теперь лежит тихо. Огонь вздохнул, и я вместе с ним. Внизу ещё кое-что осталось, сходишь?","{boss}, подумать только! Такими историями у нас пугали детей, чтобы не шалили. Присядь, у меня есть к тебе новая просьба.","Мне уже сказали, что {boss} больше не поднимется. Хорошо. Только далеко не уходи, потому что внизу есть ещё работа."],"first":["Ты по объявлению? Садись к огню. Начало там такое страшное, что дальше никто не читает, и приходят только те, кто дочитал до оплаты. За неделю такой человек нашёлся один, и вот он сидит передо мной.","Копали мы камень и пробили потолок чужой улицы. Внизу стоят дома, в них горят фонари, и кто-то там очень недоволен нашим шумом. Надо бы сходить извиниться, и я очень надеюсь, что это будешь ты."],"rescueThanks":["{@merchant} уже стоит за прилавком и пересчитывает товар, будто никуда не уходил. Мне он заявил, что его не спасали, а провожали до дому.","Я ведь за него волновался, только ему об этом не рассказывай. Спасибо тебе, дорогой человек. И соль у нас теперь снова есть, а это, поверь, тоже немало."],"story":{"boss_spider":["Жила в нижних подвалах одна мать, и детей у неё было столько, что считали их по головам. Когда пришла беда, она не ушла, потому что кто-то же должен был укрывать их по ночам.","Она приходит до сих пор, только ног у неё теперь больше, и стучат они по балкам так тихо, что младший сын принимал это за дождь. Сходи к ней, прошу тебя. Хватит ей ткать им одеяло."],"boss_necro":["Он вёл книгу усопших и вёл её честно, это я помню. Каждый умерший получал у него строчку с точной датой. А потом у него разошлись две записи, и покой для него кончился.","Он начал поднимать мёртвых, чтобы уточнить у них день смерти. Одна прачка просила прекратить, а он записал, что причина не указана. Спустись и закрой наконец его книгу, пожалуйста."],"boss_forge":["Это был самый упрямый мастер во всём кузнечном квартале. Совет заказал ему цепь на сто двадцать звеньев, чтобы поднять мост. Он ответил: принято. Совета потом не стало, и моста тоже.","А он всё куёт. У него уже девять тысяч звеньев с лишним, и цепь всё кажется ему слабой. Спустись и скажи ему, что можно положить молот. Скажи ласково, если получится."],"boss":["Наш последний мэр был хорошим человеком с хорошим лицом, и я прошу тебя это запомнить. В ночь первого снега ему вручили ключи от ворот. К утру в городе стало теплее, и люди пришли его благодарить.","Тень от него ложилась к костру, а больше хроника ничего не говорит. Я не знаю, что он тогда впустил, и знать не хочу. Спустись туда и запри за ним ворота, раз больше некому."],"boss_serpent":["Паромщик брал по две монеты с головы и никому не делал скидок, даже мне. В ночь большой воды он не взял ни с кого и нагрузил лодку так, что она ушла на дно.","Выплывшие рассказывали, что он держал её снизу, на спине, пока последний не вылез на крышу. С тех пор кто-то стучит снизу в борт, два раза, как монетами. Сходи к нему, он заждался."],"boss_colossus":["Я знал его, когда у него ещё было лицо. Он носил камни и пел, плохо и громко. Потом земля пошла вниз, и он сказал: подержу, пока вы выведете детей.","Детей вывели. За ним никто не вернулся: каждый думал, что вернулся кто-то другой. Я тоже так думал, довольно долго."]},"depths":{"9":["Дальше город стоит под водой. Вода пришла за одну ночь, и люди успели только подняться на крыши. Там до сих пор горит чья-то лампа, хотя гореть ей совершенно нечем.","Спустись туда и ступай осторожно. У воды там никого не осталось, и ей очень хочется кого-нибудь оставить у себя. Плавать ты умеешь, я надеюсь?"],"13":["Под всем этим лежит самый первый город, тот, что стоял у огня земли. Оттуда принесли этот костёр. Кто принёс, я тебе не скажу, но руки у него болят до сих пор.","Туда я и прошу тебя спуститься, дорогой человек. Там очень жарко и очень одиноко, и гостей там давно никто не ждёт. Если будет кому, передай от меня привет."]},"events":{"death1":["Огонь дрогнул, и я сразу всё понял. Тот, кто сидел здесь до тебя, ушёл вниз и наверх не поднялся. За столько лет я так и не научился к этому привыкать.","Не горюй слишком долго. Осколки той души лежат теперь у алтаря и помогут тебе пойти дальше. А ужин я готовил на двоих, так что садись и ешь."],"death":["Ещё один огонёк внизу погас. Я сижу здесь очень давно и всё равно каждый раз смотрю на шахту дольше, чем надо.","После каждого из вас тропа становится чуть короче, потому что кто-то её всё-таки протоптал. Собирайся понемногу. Огонь тебя ждёт, и я, старик, тоже."],"win":["Ты снова у огня, и на этот раз с самого дна. Я сижу и делаю вид, что у меня дым в глаза попал. Он и правда попал, не спорь.","Об этом спуске у костра будут рассказывать долго, и начну первым я. Немного приукрашу, ты уж не обижайся, иначе никто не поверит, что это правда."],"boss":["{name} больше не бродит там, внизу. Я почувствовал это даже здесь, в коленях, а колени у меня редко врут.","Тихо там будет недолго. Внизу всегда кто-нибудь ждёт следующего гостя, а следующий гость, кажется, сидит сейчас передо мной."],"rare":["«{name}», подумать только. Такие вещи случайно в руки не падают. Если {@merchant} увидит такую вещь, он начнёт приценяться раньше, чем поздоровается.","Береги эту вещь, и она побережёт тебя. Один мой знакомый обращался с такой небрежно, и теперь я рассказываю о нём только в прошедшем времени."],"away":["Давно тебя не было. {@sweeper} каждый день спрашивала о тебе, а я отвечал, что ты вот-вот появишься, хотя понятия об этом не имел.","Садись и рассказывай, где тебя носило. Глубина никуда не делась, я проверял. Она у нас как раз под ногами."],"end":["{@boss_colossus} отдыхает впервые за тысячи лет, и долгов у тебя больше нет. Можешь сложить оружие и посидеть со мной у огня, а можешь пойти туда, где кончаются карты."],"endDeep":["Кто-то, оказывается, строил и под первым городом, и мне очень хочется знать, кто это был. Останешься у огня или пойдёшь выяснять?"],"cls":["Перед тобой вниз ходил {cls}. Он хвалил мой суп, а суп был так себе, так что человек это был добрый."]}}};
})(typeof window !== 'undefined' ? window : globalThis);
